const PlaywrightWrapper = require("../Framework/src/helper/wrapper/PlaywrightWrappers");

class LoginPage {
    constructor(page, logger) {
        this.page = page;
        this.logger = logger;
        this.base = new PlaywrightWrapper(page, logger);
        this.Elements = {
            usernameInput: "[data-test='username']",
            passwordInput: "[data-test='password']",
            loginButton: "[data-test='login-button']",
            errorBanner: "[data-test='error']",
            errorCloseButton: "[data-test='error-button']"
        };
    }

    async navigateToLoginPage() {
        await this.base.goto("/");
    }

    async enterUsername(username) {
        await this.base.typeText(this.Elements.usernameInput, username, "Username Field");
    }

    async enterPassword(password) {
        await this.base.typePassword(this.Elements.passwordInput, password, "Password Field");
    }

    async clickLoginButton() {
        await this.base.waitAndClick(this.Elements.loginButton, "Login Button");
    }

    async login(username, password) {
        await this.enterUsername(username);
        await this.enterPassword(password);
        await this.clickLoginButton();
    }

    async isErrorVisible() {
        return this.base.isVisible(this.Elements.errorBanner);
    }

    async getErrorText() {
        return this.base.textContent(this.Elements.errorBanner);
    }
}

module.exports = LoginPage;
